import React, { useState } from 'react';
import { Card, Spinner } from 'react-bootstrap';
import axios from 'axios';

function Terminal() {
  const [output, setOutput] = useState([
    { text: 'CoreX OS Terminal', type: 'system' },
    { text: 'Type "help" for available commands', type: 'system' },
    { text: '', type: 'normal' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleCommand = async (cmd) => {
    if (!cmd.trim()) return;
    
    // Add command to output
    const newOutput = [...output, `CoreX> ${cmd}`];
    setOutput(newOutput);
    setInput('');
    
    // Handle local commands
    if (cmd.trim() === 'clear') {
      setOutput(['CoreX OS Terminal', '']);
      return;
    }
    
    // Send command to backend
    setLoading(true);
    try {
      const response = await axios.post('http://localhost:5000/api/shell/execute', {
        command: cmd
      });
      
      // Add response to output
      if (response.data.output) {
        const outputLines = response.data.output.split('\n');
        setOutput([...newOutput, ...outputLines, '']);
      } else if (response.data.error) {
        setOutput([...newOutput, `Error: ${response.data.error}`, '']);
      } else {
        setOutput([...newOutput, 'Command executed successfully', '']);
      }
    } catch (error) {
      console.error('Error executing command:', error);
      setOutput([...newOutput, 
        'Error: Could not connect to backend',
        'Make sure the Flask server is running on http://localhost:5000',
        'Note: Terminal commands require the C core to be running',
        ''
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card>
      <Card.Header>
        <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
          <span>Terminal</span>
          {loading && <Spinner animation="border" size="sm" />}
        </div>
      </Card.Header>
      <Card.Body>
        <div className="terminal" style={{
          backgroundColor: '#1e1e1e',
          color: '#00ff00',
          fontFamily: 'Consolas, monospace',
          padding: '10px',
          minHeight: '400px',
          maxHeight: '600px',
          overflowY: 'auto',
          borderRadius: '4px'
        }}>
          {output.map((line, i) => (
            <div key={i} style={{whiteSpace: 'pre-wrap'}}>{line}</div>
          ))}
          <div style={{display: 'flex', alignItems: 'center'}}>
            <span style={{color: '#00ff00'}}>CoreX&gt; </span>
            <input
              style={{
                backgroundColor: 'transparent',
                border: 'none',
                color: '#00ff00',
                fontFamily: 'Consolas, monospace',
                outline: 'none',
                flex: 1,
                marginLeft: '5px'
              }}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') handleCommand(input);
              }}
              disabled={loading}
              autoFocus
            />
          </div>
        </div>
      </Card.Body>
    </Card>
  );
}

export default Terminal;
